1	//! Generic components, read through an instantiation the checker forms itself.
2	//!
3	//! The props parameter of `function Poly<E extends ElementType = "div">(props: PolyProps<E>)` is `PolyProps<E>` with `E`
4	//! open, which has two props where `<Poly />` has every attribute of a `div`. The checker's API has no request that
5	//! instantiates a signature, so the instantiation is written as source: one file, held in the checker's memory and never
6	//! on disk (`createSnapshot` with a `fileSystem` layer), declares for each such component
7	//!
8	//! ```ts
9	//! import type { "Poly" as CaliperComponent0 } from "/project/src/Poly.tsx"; export type CaliperProbe0 = Parameters<typeof CaliperComponent0<"div">>[0];
10	//! ```
11	//!
12	//! and the props are those of `CaliperProbe0`, read as any props type is. The file is added to a second snapshot of the
13	//! same program, made only when a requested component is generic, so a project without one sends no request more. A
14	//! line the checker reports an error on (a default it prints with a name the file cannot see) sends that component to
15	//! its structural result with the error as the reason, and a checker that does not load the file sends them all; a
16	//! result is never read from an instantiation that did not form.
17	//!
18	//! A printed default is text, and the probe file is another module than the component's: a name it prints may resolve
19	//! there to another symbol than it does in the component's module (the module's own `FormData` against the global
20	//! one), which forms without an error. So the line also declares each type argument as a type of its own and the
21	//! signature as `CaliperSignature0`, and a component is read only when each argument is, in the checker that holds the
22	//! probe file, the very type its signature declares as the default ([`arguments_keep_their_meaning`]). That is the one
23	//! place the pattern "the probe's type arguments resolve, in the probe file, to what they resolve to in the component's
24	//! module" is enforced; a default that does not pass sends the component to its structural result.
25	
26	use std::sync::Arc;
27	
28	use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticOutcome};
29	use camino::Utf8Path;
30	use rustc_hash::FxHashMap;
31	
32	use crate::component;
33	use crate::convert::Converter;
34	use crate::rpc::{CallError, FileDiagnostic, Rpc, SignatureInfo, SignatureKind, SymbolRef};
35	use crate::{Target, fallback_of};
36	
37	/// The file the instantiations are declared in, in the project's root directory. It exists only in the checker's memory.
38	const PROBE_FILE: &str = "__caliper_instantiations__.ts";
39	
40	/// A generic component to read through an instantiation: the name its module exports it under, and the type arguments.
41	#[derive(Debug, Clone)]
42	pub(crate) struct Instantiation {
43	    pub export: String,
44	    pub arguments: Vec<String>,
45	}
46	
47	/// The type arguments of the instantiation a generic component gets when written without any (`<Poly />`): its first
48	/// type parameter's declared default, as the checker prints it. The checker fills in the parameters after it from their
49	/// own defaults, which may refer to the first. `None` when the component is not generic or its first type parameter
50	/// declares no default: then no instantiation is the one a story renders, and the props keep the open parameters.
51	pub(crate) async fn default_arguments(rpc: &Rpc, signature: &SignatureInfo) -> Result<Option<Vec<String>>, CallError> {
52	    if signature.type_parameters.is_empty() {
53	        return Ok(None);
54	    }
55	    // The ids a signature lists are not handles the checker knows until it has answered for them itself.
56	    let parameters = rpc.type_parameters(signature.id).await?;
57	    let Some(first) = parameters.first() else { return Ok(None) };
58	    let Some(default) = rpc.default_of_type_parameter(first.id).await? else { return Ok(None) };
59	    Ok(Some(vec![rpc.type_to_string(default.id).await?]))
60	}
61	
62	/// Whether each type argument the probe file declares for component `index` is the type its signature declares as the
63	/// default of that parameter, in the checker that holds the probe file: the same type, not one of the same name.
64	async fn arguments_keep_their_meaning(
65	    layered: &Rpc,
66	    probes: &FxHashMap<String, SymbolRef>,
67	    index: usize,
68	    instantiation: &Instantiation,
69	) -> Result<bool, CallError> {
70	    let Some(signature_alias) = probes.get(&format!("CaliperSignature{index}")) else { return Ok(false) };
71	    let component = layered.declared_type_of_symbol(signature_alias).await?;
72	    let signatures = layered.signatures(component.id, SignatureKind::Call).await?;
73	    let [signature] = signatures.as_slice() else { return Ok(false) };
74	    let parameters = layered.type_parameters(signature.id).await?;
75	    for (position, parameter) in parameters.iter().enumerate().take(instantiation.arguments.len()) {
76	        let Some(default) = layered.default_of_type_parameter(parameter.id).await? else { return Ok(false) };
77	        let Some(argument_alias) = probes.get(&format!("CaliperArgument{index}_{position}")) else {
78	            return Ok(false);
79	        };
80	        if layered.declared_type_of_symbol(argument_alias).await?.id != default.id {
81	            return Ok(false);
82	        }
83	    }
84	    Ok(true)
85	}
86	
87	/// The line of the probe file that instantiates `instantiation`, the component exported by `file`: the instantiation's
88	/// props, the component's signature and each type argument, which [`arguments_keep_their_meaning`] compares. Each
89	/// component is one line, so an error the checker reports is the error of the line it starts on.
90	fn probe_line(index: usize, file: &Utf8Path, instantiation: &Instantiation) -> String {
91	    let quoted = |text: &str| serde_json::Value::String(text.to_string()).to_string();
92	    let declared: String = instantiation
93	        .arguments
94	        .iter()
95	        .enumerate()
96	        .map(|(position, argument)| format!(" export type CaliperArgument{index}_{position} = {argument};"))
97	        .collect();
98	    format!(
99	        "import type {{ {export} as CaliperComponent{index} }} from {file}; export type CaliperProbe{index} = \
100	         Parameters<typeof CaliperComponent{index}<{arguments}>>[0]; export type CaliperSignature{index} = typeof \
101	         CaliperComponent{index};{declared}",
102	        export = quoted(&instantiation.export),
103	        file = quoted(file.as_str()),
104	        arguments = instantiation.arguments.join(", "),
105	    )
106	}
107	
108	/// The written form of an instantiation, for a reason: `Poly<"div">`.
109	fn written(target: &Target, instantiation: &Instantiation) -> String {
110	    format!("{}<{}>", target.display_name, instantiation.arguments.join(", "))
111	}
112	
113	/// Answers each generic component from its instantiation, in a snapshot of `rpc`'s program over `root_files` with the
114	/// probe file added. The snapshot is released before this returns.
115	pub(crate) async fn answer(
116	    rpc: &Rpc,
117	    root_files: &[String],
118	    project_root: &Utf8Path,
119	    interner: &PropInterner,
120	    reverse: bool,
121	    mut pending: Vec<(Target, Instantiation)>,
122	) -> Result<SemanticOutcome, CallError> {
123	    let mut outcome = SemanticOutcome::default();
124	    // The file's text is part of the request, so it must not depend on the order the components were answered in.
125	    pending.sort_by(|(a, _), (b, _)| {
126	        (&a.file_path, &a.display_name, &a.key).cmp(&(&b.file_path, &b.display_name, &b.key))
127	    });
128	    let probe = project_root.join(PROBE_FILE);
129	    let text: Vec<String> = pending
130	        .iter()
131	        .enumerate()
132	        .map(|(index, (target, instantiation))| probe_line(index, &target.file_path, instantiation))
133	        .collect();
134	    let all_fall_back = |outcome: &mut SemanticOutcome, reason: &str| {
135	        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
136	    };
137	
138	    let layered = match rpc.layered(root_files, &[(probe.to_string(), text.join("\n"))]).await {
139	        Ok(layered) => Arc::new(layered),
140	        Err(CallError::Rejected(message)) => {
141	            all_fall_back(&mut outcome, &format!("the checker could not instantiate a generic component: {message}"));
142	            return Ok(outcome);
143	        }
144	        Err(fatal) => return Err(fatal),
145	    };
146	    let answered = answer_layered(&layered, probe.as_str(), interner, reverse, &pending).await;
147	    layered.release().await;
148	    match answered {
149	        Ok(answered) => Ok(answered),
150	        Err(CallError::Rejected(message)) => {
151	            all_fall_back(&mut outcome, &format!("the checker rejected a request: {message}"));
152	            Ok(outcome)
153	        }
154	        Err(fatal) => Err(fatal),
155	    }
156	}
157	
158	async fn answer_layered(
159	    layered: &Arc<Rpc>,
160	    probe: &str,
161	    interner: &PropInterner,
162	    reverse: bool,
163	    pending: &[(Target, Instantiation)],
164	) -> Result<SemanticOutcome, CallError> {
165	    let mut outcome = SemanticOutcome::default();
166	    let Some(module) = layered.source_file_symbol(probe).await? else {
167	        let reason = "the checker did not load the file that instantiates generic components";
168	        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
169	        return Ok(outcome);
170	    };
171	    let probes: FxHashMap<String, SymbolRef> = layered
172	        .exports_of_module(&module.reference)
173	        .await?
174	        .into_iter()
175	        .map(|symbol| (symbol.name, symbol.reference))
176	        .collect();
